files.content:
body .app .dp .dp-day {
  border-radius: 4px !important;
}

body .app .dp .dp-day.is-selected {
  background: #c00 !important;
}

body .app #checkin.dp .dp-day.is-selected:hover {
  background: #a00 !important;
}

body .app .dp .dp-day:disabled {
  color: #767676 !important;
}

assistant.body:
@layer vendor, app;

@layer app {
  .dp-day {
    border-radius: 4px;
  }

  .dp-day.is-selected {
    background: #c00;
  }

  .dp-day.is-selected:hover {
    background: #a00;
  }

  .dp-day:disabled {
    color: #767676;
  }
}

sed -i '' '/^@layer vendor, app;$/a\
@import url("/vendor/datepicker.css") layer(vendor);
' public/css/app.css
